using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.Build;using UnityEditor.Build.Reporting;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;
public static class NightPlayerBuild {
 [Serializable]class Report{public bool pass,targetSupported;public string error,unity,target,backend,result,scene,executable;public ulong bytes;public double seconds;public int warnings,errors;public string[] ids,shaders;}
 static string Arg(string flag){var a=Environment.GetCommandLineArgs();return a[Array.IndexOf(a,flag)+1];}
 public static void Run(){var r=new Report{unity=Application.unityVersion,target="StandaloneWindows64",backend=PlayerSettings.GetScriptingBackend(NamedBuildTarget.Standalone).ToString()};string output=Arg("-buildOutput"),directory=Path.GetDirectoryName(output);Directory.CreateDirectory(directory);var oldRP=GraphicsSettings.defaultRenderPipeline;var oldQuality=QualitySettings.renderPipeline;int code=0;try{
  r.targetSupported=BuildPipeline.IsBuildTargetSupported(BuildTargetGroup.Standalone,BuildTarget.StandaloneWindows64);if(!r.targetSupported)throw new Exception("Installed Windows standalone build support unavailable");if(PlayerSettings.GetScriptingBackend(NamedBuildTarget.Standalone)!=ScriptingImplementation.Mono2x)throw new Exception("This probe expects installed Mono backend; backend was not changed");
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);string folder=AssetDatabase.GenerateUniqueAssetPath("Assets/NightPlayerProof");AssetDatabase.CreateFolder("Assets",Path.GetFileName(folder));var rd=ScriptableObject.CreateInstance<UniversalRendererData>();AssetDatabase.CreateAsset(rd,folder+"/Renderer.asset");var rp=UniversalRenderPipelineAsset.Create(rd);rp.shadowDistance=30;var so=new SerializedObject(rp);so.FindProperty("m_MainLightShadowsSupported").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();AssetDatabase.CreateAsset(rp,folder+"/Pipeline.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.35f,.35f,.35f);var sun=new GameObject("Proof sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=2.1f;sun.shadows=LightShadows.Hard;sun.transform.rotation=Quaternion.LookRotation(new Vector3(-5,-9,-4));RenderSettings.sun=sun;
  var data=SmallPropsV1.Read(Path.Combine(Arg("-props-export"),"small_props.json"));var built=MapSharedPropsBuilder.Build(Arg("-props-export"));var ids=new[]{"treasurechest_worn","treasurechest","treasurechest_reinforced","treasurechest_ornate","treasurechest_silver","treasurechest_gold","treasurechest_rainbow","tiedsack","coiledrope","ruinwall"};if(Array.IndexOf(Environment.GetCommandLineArgs(),"-probe-mausoleum")>=0)ids[9]="mausoleum";var controller=new GameObject("Isolated Player validation").AddComponent<NightPlayerProbe>();controller.ids=ids;controller.prefabs=ids.Select(id=>built.prefabs[id]).ToArray();controller.sinks=ids.Select(id=>Array.Find(data.assets,a=>a.id==id).groundSink).ToArray();controller.heights=ids.Select(id=>Array.Find(data.assets,a=>a.id==id).height).ToArray();controller.colliderCounts=controller.prefabs.Select(p=>p.GetComponentsInChildren<Collider>(true).Length).ToArray();controller.expectedShaders=controller.prefabs.Select(p=>p.GetComponent<Renderer>().sharedMaterial.shader.name).ToArray();UnityEngine.Object.DestroyImmediate(built.root);r.ids=ids;r.shaders=controller.expectedShaders;
  var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.name="Isolated proof floor";floor.transform.localScale=Vector3.one*4;var fm=new Material(Shader.Find("Universal Render Pipeline/Lit"));fm.SetColor("_BaseColor",new Color(.22f,.17f,.11f));AssetDatabase.CreateAsset(fm,folder+"/Floor.mat");controller.floor=floor.GetComponent<Renderer>();controller.floor.sharedMaterial=fm;var camera=new GameObject("Player proof camera").AddComponent<Camera>();camera.gameObject.AddComponent<UniversalAdditionalCameraData>();camera.fieldOfView=50;camera.farClipPlane=300;camera.nearClipPlane=.02f;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;controller.proofCamera=camera;controller.EditorCapture(directory);r.scene=folder+"/PlayerProof.unity";EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),r.scene);AssetDatabase.SaveAssets();r.executable=output;
  var build=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{r.scene},locationPathName=output,target=BuildTarget.StandaloneWindows64,subtarget=(int)StandaloneBuildSubtarget.Player,options=BuildOptions.Development});r.result=build.summary.result.ToString();r.bytes=build.summary.totalSize;r.seconds=build.summary.totalTime.TotalSeconds;r.warnings=build.summary.totalWarnings;r.errors=build.summary.totalErrors;r.pass=build.summary.result==BuildResult.Succeeded;if(!r.pass)code=1;
 }catch(Exception e){r.error=e.ToString();Debug.LogException(e);code=1;}finally{GraphicsSettings.defaultRenderPipeline=oldRP;QualitySettings.renderPipeline=oldQuality;AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(directory,"build-report.json"),JsonUtility.ToJson(r,true));EditorApplication.Exit(code);}}
}
